    ('grn_history', 'grns'),
    ('vendor_bills', 'vendor_bills'),
    ('vendor_bill_lines', 'vendor_bills'),
    ('vendor_bill_payments', 'vendor_bills'),
    ('vendor_bill_history', 'vendor_bills'),
    ('debit_notes', 'debit_notes'),
    ('material_requisitions', 'requisitions'),
    ('material_requisition_lines', 'requisitions'),
    ('material_requisition_history', 'requisitions'),
    ('stock_ledger', 'stock_ledger'),
    ('stock_adjustments', 'stock_adjustments'),
    ('stock_adjustment_history', 'stock_adjustments')
  ) AS v(t, c) LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('REVOKE ALL ON public.%I FROM anon', t);
    EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated', t);
    EXECUTE format('GRANT ALL ON public.%I TO service_role', t);
    EXECUTE format('DROP POLICY IF EXISTS "ERP staff: read" ON public.%I', t);
    EXECUTE format('DROP POLICY IF EXISTS "ERP staff: insert" ON public.%I', t);
    EXECUTE format('DROP POLICY IF EXISTS "ERP staff: update" ON public.%I', t);
    EXECUTE format('DROP POLICY IF EXISTS "ERP staff: delete" ON public.%I', t);
    EXECUTE format('CREATE POLICY "ERP staff: read" ON public.%I FOR SELECT TO authenticated USING ((SELECT public.erp_can_read()))', t);
    EXECUTE format('CREATE POLICY "ERP staff: insert" ON public.%I FOR INSERT TO authenticated WITH CHECK ((SELECT public.erp_can_write(%L)))', t, c);
    EXECUTE format('CREATE POLICY "ERP staff: update" ON public.%I FOR UPDATE TO authenticated USING ((SELECT public.erp_can_write(%L))) WITH CHECK ((SELECT public.erp_can_write(%L)))', t, c, c);
    EXECUTE format('CREATE POLICY "ERP staff: delete" ON public.%I FOR DELETE TO authenticated USING ((SELECT public.erp_can_delete(%L)))', t, c);
    EXECUTE format('DROP TRIGGER IF EXISTS erp_touch ON public.%I', t);
    EXECUTE format('CREATE TRIGGER erp_touch BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.erp_touch()', t);
    EXECUTE format('ALTER TABLE public.%I REPLICA IDENTITY FULL', t);
    IF EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime')
       AND NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = t) THEN
      EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I', t);
    END IF;
  END LOOP;
END $sec$;

-- Loads the sample data sent by the app ({table: rows[]}) in one transaction.
-- Allowed on an empty database for any staff member, or for an administrator with wipe = true
-- (Reset demo data), which first empties every ERP table.
CREATE OR REPLACE FUNCTION public.erp_load_sample(payload jsonb, wipe boolean DEFAULT false)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NOT public.erp_is_staff() THEN RAISE EXCEPTION 'Sign in as a staff member first.' USING ERRCODE = '42501'; END IF;
  IF wipe THEN
    IF NOT public.erp_is_admin() THEN RAISE EXCEPTION 'Only an administrator can reset the data.' USING ERRCODE = '42501'; END IF;
    TRUNCATE public.doc_counters, public.material_categories, public.uoms, public.lead_sources, public.lead_stages, public.activity_types, public.contact_roles, public.departments, public.designations, public.states, public.company, public.product_families, public.bom_groups, public.item_kinds, public.roles, public.role_permissions, public.role_approvals, public.staff, public.customers, public.customer_contacts, public.leads, public.activities, public.quotations, public.quotation_lines, public.quotation_history, public.sales_orders, public.sales_order_lines, public.sales_order_payments, public.invoices, public.invoice_lines, public.invoice_payments, public.delivery_challans, public.delivery_challan_lines, public.installed_machines, public.service_tickets, public.products, public.product_specs, public.child_items, public.child_item_specs, public.materials, public.material_units, public.boms, public.bom_lines, public.bom_versions, public.combo_sets, public.combo_set_lines, public.combo_set_history, public.work_orders, public.vendors, public.indents, public.indent_lines, public.indent_history, public.purchase_orders, public.purchase_order_lines, public.purchase_order_history, public.gate_passes, public.gate_pass_lines, public.gate_pass_history, public.grns, public.grn_lines, public.grn_history, public.vendor_bills, public.vendor_bill_lines, public.vendor_bill_payments, public.vendor_bill_history, public.debit_notes, public.material_requisitions, public.material_requisition_lines, public.material_requisition_history, public.stock_ledger, public.stock_adjustments, public.stock_adjustment_history CASCADE;
  ELSIF NOT public.erp_store_empty() THEN
    RAISE EXCEPTION 'The database already has data.' USING ERRCODE = '42501';
  END IF;
  INSERT INTO public.doc_counters (name, value, updated_by)
    SELECT name, value, updated_by FROM jsonb_populate_recordset(NULL::public.doc_counters, payload -> 'doc_counters')
    ON CONFLICT (name) DO UPDATE SET value = greatest(doc_counters.value, EXCLUDED.value);
  INSERT INTO public.material_categories (code, name, bin, lead_days, vendor_id, sort_order, extra, updated_by)
    SELECT code, name, bin, lead_days, vendor_id, sort_order, extra, updated_by FROM jsonb_populate_recordset(NULL::public.material_categories, payload -> 'material_categories');
  INSERT INTO public.uoms (code, name, sort_order, extra, updated_by)
    SELECT code, name, sort_order, extra, updated_by FROM jsonb_populate_recordset(NULL::public.uoms, payload -> 'uoms');
  INSERT INTO public.lead_sources (code, name, sort_order, extra, updated_by)
    SELECT code, name, sort_order, extra, updated_by FROM jsonb_populate_recordset(NULL::public.lead_sources, payload -> 'lead_sources');
  INSERT INTO public.lead_stages (code, name, sort_order, extra, updated_by)
    SELECT code, name, sort_order, extra, updated_by FROM jsonb_populate_recordset(NULL::public.lead_stages, payload -> 'lead_stages');
  INSERT INTO public.activity_types (code, name, sort_order, extra, updated_by)
